@use 'tremplin/scss/config' with ($gradient: linear-gradient(135deg, #e6efff, #fff));
@use 'tremplin/scss/mixins/gradients' as gradient;
@use 'tremplin/scss/tremplin-utilities';
.three-color-x { @include gradient.gradient-x-three-colors(red, gold, 40%, blue); }
.three-color-y { @include gradient.gradient-y-three-colors(red, gold, 60%, blue); }

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: ('display': (property: display, class: d, responsive: true, print: true, values: (block: block, none: none)))
);

@use 'tremplin/scss' with (
  $spacers: (2: .75rem),
  $utilities: (
    'column-gap': (
      property: column-gap, class: column-gap, responsive: true,
      important: false, values: (tight: .25rem)
    )
  )
);

@use 'tremplin/scss' with (
  $utilities: (
    'grid-column-counts': (
      property: grid-template-columns, class: grid-cols,
      responsive: true, values: (5: repeat(5, 1fr))
    )
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: (
    'width': (property: width, class: w, values: (min: 10rem, 100: 100%)),
    'height': (property: height, class: h, values: (min: 10rem, 100: 100%))
  )
);

@use 'tremplin/scss/tremplin-utilities' with (
  $utilities: ('underline-thickness': (property: text-decoration-thickness, class: underline-thickness, state: hover focus-visible, values: (4: 4px)))
);
